// ============================================================================
//  PORTRAITS -- illustrated reference art for character creation and the
//  party menu. One image per race, one per class -- not per combination -- so
//  a race screen shows the race art and a class screen shows the class art.
//  The in-world sprite (overworld, battle) stays procedural pixel art; these
//  are only used where a bigger, static illustration fits: creation and menus.
// ============================================================================

export const RACE_PORTRAITS = {
  human: 'data:image/jpeg;base64,',
  elf: 'data:image/jpeg;base64,',
  dwarf: 'data:image/jpeg;base64,',
  fairy: 'data:image/jpeg;base64,',
  saurian: 'data:image/jpeg;base64,',
  lupine: 'data:image/jpeg;base64,',
  ogrekin: 'data:image/jpeg;base64,',
  gnome: 'data:image/jpeg;base64,',
  merfolk: 'data:image/jpeg;base64,',
  draconian: 'data:image/jpeg;base64,',
  automaton: 'data:image/jpeg;base64,',
  revenant: 'data:image/jpeg;base64,',
};

export const CLASS_PORTRAITS = {
  warrior: 'data:image/jpeg;base64,',
  guardian: 'data:image/jpeg;base64,',
  monk: 'data:image/jpeg;base64,',
  lancer: 'data:image/jpeg;base64,',
  thief: 'data:image/jpeg;base64,',
  archer: 'data:image/jpeg;base64,',
  dancer: 'data:image/jpeg;base64,',
  jester: 'data:image/jpeg;base64,',
  mage: 'data:image/jpeg;base64,',
  cleric: 'data:image/jpeg;base64,',
  summoner: 'data:image/jpeg;base64,',
  spiritist: 'data:image/jpeg;base64,',
};

const _cache = new Map();
function loadImg(src) {
  if (_cache.has(src)) return _cache.get(src);
  const img = new Image();
  img.src = src;
  _cache.set(src, img);
  return img;
}

/** An HTMLImageElement for a race portrait, or null if the race id is unknown. */
export function racePortrait(raceId) {
  const src = RACE_PORTRAITS[raceId];
  return src ? loadImg(src) : null;
}

/** An HTMLImageElement for a class portrait, keyed by ROOT class id. */
export function classPortrait(rootId) {
  const src = CLASS_PORTRAITS[rootId];
  return src ? loadImg(src) : null;
}
